#[derive(Clone, Debug)]
pub struct ResolvedConfig {
    pub root: PathBuf,
    pub changesets_dir: PathBuf,
    pub cascade: CascadeConfig,
    pub validation: ValidationConfig,
    pub registries: BTreeMap<RegistryKey, RegistryConfig>,
    /// Per-package override rules from `[[package]]` blocks, in TOML declaration order.
    ///
    /// Lookup uses two-pass specificity (see `resolve_package_config`):
    /// - Pass 1 (Prefixed tier): the first entry whose `rule_id.ecosystem().is_some()` AND
    ///   `rule_id.matches(pkg_id)` is true wins, regardless of its position relative to Bare rules.
    /// - Pass 2 (Bare tier): only if Pass 1 finds nothing, the first entry where
    ///   `rule_id.matches(pkg_id)` is true wins.
    ///   Within each tier, first-match-wins in TOML declaration order.
    pub packages: Vec<(PackageId, PackageConfig)>,
    /// Bulk config-override rules from `[[package-set]]` blocks, in TOML declaration order.
    /// Applied as a fallback when no `[[package]]` rule matches a package.
    /// Unlike `[[package]]` (exact `PackageId` match, first-wins), each
    /// `[[package-set]]` rule uses a glob pattern and can match many packages simultaneously.
    pub package_sets: Vec<(PackagePattern, PackageConfig)>,
    pub groups: GroupTable,
    /// Raw group declarations from `callisto.toml`, kept so that
    /// `Workspace::load` can call `GroupTable::resolve` once the
    /// `IdentityIndex` is available after `ManifestWalkResolver::build`.
    pub(crate) raw_groups: RawGroupTable,
    pub promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
    provenance: BTreeMap<ConfigKey, ConfigProvenance>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConfigProvenance {
    Default,
    Explicit,
}

impl ResolvedConfig {
    pub(crate) fn with_promoted_siblings(
        &self,
        promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
    ) -> ResolvedConfig {
        let mut overlay = self.clone();
        overlay.promoted_siblings = promoted_siblings;
        overlay
    }

    pub fn provenance(&self, key: &ConfigKey) -> ConfigProvenance {
        self.provenance.get(key).copied().unwrap_or(ConfigProvenance::Default)
    }

    pub fn rendered_value(&self, key: &ConfigKey) -> Option<String> {
        if key == &ConfigKey::CASCADE_MODE {
            Some(match self.cascade.mode {
                CascadeMode::OutOfRange => "out-of-range".to_string(),
                CascadeMode::Always => "always".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_BUMP_SEVERITY {
            Some(match self.cascade.bump_severity {
                CascadeBumpSeverity::Patch => "patch".to_string(),
                CascadeBumpSeverity::Minor => "minor".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_PEER_ESCALATION {
            Some(self.cascade.peer_escalation.to_string())
        } else if key == &ConfigKey::CASCADE_PRESERVE_NPM_RANGES {
            Some(self.cascade.preserve_npm_ranges.to_string())
        } else if key == &ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS {
            Some(self.validation.allow_empty_changesets.to_string())
        } else {
            None
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CascadeConfig {
    pub mode: CascadeMode,
    pub bump_severity: CascadeBumpSeverity,
    pub peer_escalation: bool,
    pub preserve_npm_ranges: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeMode {
    OutOfRange,
    Always,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeBumpSeverity {
    Patch,
    Minor,
}

impl CascadeBumpSeverity {
    pub fn as_severity(self) -> Severity {
        match self {
            CascadeBumpSeverity::Patch => Severity::Patch,
            CascadeBumpSeverity::Minor => Severity::Minor,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ValidationConfig {
    pub allow_empty_changesets: bool,
}

#[derive(Clone, Debug)]
pub struct RegistryConfig {
    pub kind: Ecosystem,
    pub url: Option<String>,
}

/// Per-package overrides from a `[[package]]` block in `callisto.toml`.
///
/// Every field is `Option<T>` — `None` means "not specified; use the package's default."
/// Only fields that the user explicitly set in the `[[package]]` block are `Some`.
#[derive(Clone, Debug)]
pub struct PackageConfig {
    pub release_trigger: Option<ReleaseTrigger>,
    pub publish_to: Option<Vec<PublishTarget>>,
    pub tag_template: Option<TagTemplate>,
    /// Changelog path relative to the package's own root directory.
    pub changelog: Option<PathBuf>,
    pub pre_major_inference: Option<PreMajorInferencePolicy>,
}

/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
/// false, feat_to_patch: true}`-shaped struct literal could otherwise
/// construct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
    ConservativeFeat,
}

pub fn parse_publish_target(s: &str) -> Result<PublishTarget, ConfigError> {
    match s {
        "crates-io" => Ok(PublishTarget::CratesIo),
        "npm" => Ok(PublishTarget::Npm {
            registry: None,
            access: None,
        }),
        "pypi" => Ok(PublishTarget::Pypi { index: None }),
        "nuget" => Ok(PublishTarget::NuGet { source: None }),
        "github-release" => Ok(PublishTarget::GitHubRelease),
        "none" => Ok(PublishTarget::None),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("publish-to = {other:?}"),
        }),
    }
}

pub fn parse_release_trigger(s: &str) -> Result<ReleaseTrigger, ConfigError> {
    match s {
        "changeset" => Ok(ReleaseTrigger::Changeset),
        "auto" => Ok(ReleaseTrigger::Auto),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("release-trigger = {other}"),
        }),
    }
}

/// Two-pass `[[package]]` rule lookup with Prefixed-over-Bare specificity.
///
/// Pass 1: iterate `cfg.packages` in TOML-declaration order, return the
/// first entry where `rule_id.ecosystem().is_some()` AND
/// `rule_id.matches(id)` -- prefixed rules (`cargo/`, `npm/`, `pypi/`)
/// always beat bare ones regardless of declaration order.
///
/// Pass 2 (only if Pass 1 found nothing): same order, first entry where
/// `rule_id.matches(id)` with no ecosystem restriction.
///
/// `None` if neither pass matches.
///
/// MUST NOT sort or partition `cfg.packages` -- specificity comes solely
/// from two separate linear scans over the unmodified slice.
pub(crate) fn resolve_package_config<'a>(
    id: &PackageId,
    cfg: &'a ResolvedConfig,
) -> Result<Option<&'a PackageConfig>, GraphError> {
    if let Some((_, pcfg)) = cfg
        .packages
        .iter()
        .find(|(rule_id, _)| rule_id.ecosystem().is_some() && rule_id.matches(id))
    {
        return Ok(Some(pcfg));
    }
    if let Some((_, pcfg)) = cfg.packages.iter().find(|(rule_id, _)| rule_id.matches(id)) {
        if let Some(siblings) = cfg.promoted_siblings.get(id.name()) {
            return Err(GraphError::AmbiguousName {
                name: id.name().to_string(),
                candidates: siblings.iter().map(|(pid, _)| pid.clone()).collect(),
            });
        }
        return Ok(Some(pcfg));
    }
    Ok(None)
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

use crate::{ApplyPermit, PackageId, Version};
use std::time::Duration;

#[derive(Debug, thiserror::Error, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum RegistryError {
    #[error("Rate limited. Retry after {0:?}")]
    RateLimited(Duration),
    #[error("Authentication failed: {0}")]
    AuthFailed(String),
    /// Distinct network-layer failure (e.g. DNS resolution, TCP connect
    /// timeout) separate from a registry-level auth or rate-limit response.
    /// Reserved for registry implementations that can reliably distinguish
    /// network failures from other errors; `SubprocessRegistryClient` currently
    /// maps all unrecognised subprocess failures to `Other`.
    #[error("Network error: {0}")]
    Network(String),
    #[error("Other registry error: {0}")]
    Other(String),
}

impl RegistryError {
    /// Returns a camelCase string identifying the variant for use as a
    /// machine-readable discriminator in JSON output. Matches the `errorKind`
    /// field on `PublishAttemptResult::Failed`.
    pub fn kind_str(&self) -> &'static str {
        match self {
            RegistryError::RateLimited(_) => "rateLimited",
            RegistryError::AuthFailed(_) => "authFailed",
            RegistryError::Network(_) => "network",
            RegistryError::Other(_) => "other",
        }
    }
}

/// Outcome of a [`RegistryClient::publish`] call that did not error.
///
/// Ecosystem CLI publishers (`cargo publish`, `npm publish`, `twine upload`)
/// commonly treat "this version is already on the index" as their own
/// success/idempotent case rather than a distinct pre-check result. Surfacing
/// that here lets `publish` itself be the source of truth for "already
/// published", instead of requiring every ecosystem to implement a reliable
/// CLI-only [`RegistryClient::is_published`] pre-check (some ecosystems have
/// none without reaching for the registry's HTTP API, which this design
/// deliberately avoids).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PublishOutcome {
    /// The package/version was newly uploaded to the registry by this call.
    Published,
    /// The package/version was already present on the registry; this call
    /// took no publishing action.
    AlreadyPublished,
}

pub trait RegistryClient: Send + Sync {
    /// Best-effort, optional pre-check for whether `package@version` is
    /// already on the registry. Implementations may always return `Ok(false)`
    /// when no reliable CLI-only check exists for their ecosystem — in that
    /// case `publish`'s own [`PublishOutcome::AlreadyPublished`]
    /// classification is the real source of truth, and callers must not
    /// treat `Ok(false)` here as a guarantee the package is unpublished.
    fn is_published(&self, package: &PackageId, version: &Version) -> Result<bool, RegistryError>;

    /// Publishes `package@version`, or reports that it was already published
    /// as a non-error, non-action outcome.
    ///
    /// The highest-stakes side effect in the codebase -- an upload to a public
    /// registry is not revertible -- so it requires an [`ApplyPermit`]. A dry
    /// run cannot obtain one and therefore cannot reach this method.
    /// [`Self::is_published`] is read-only and needs no permit.
    fn publish(
        &self,
        package: &PackageId,
        version: &Version,
        permit: &ApplyPermit,
    ) -> Result<PublishOutcome, RegistryError>;
}

/// Gate on whether a publish retry should proceed after a registry reports
/// [`RegistryError::RateLimited`]. Called with the registry-supplied `retry_after` duration
/// immediately before the caller would sleep and retry; returning `Err` aborts the retry
/// instead (the `?`-propagated error becomes the publish attempt's final failure). The
/// production implementation (`AlwaysRetryPolicy`, `callisto-graph`) always permits the
/// retry — the caller's own overall wait-time cutoff is what bounds retries, not this trait —
/// but the seam exists so a caller with a stricter policy (or a test asserting retry
/// behavior without real waiting) can substitute one without touching the retry loop itself.
pub trait RateLimitPolicy: Send + Sync {
    fn check_rate_limit(&self, retry_after: Duration) -> Result<(), RegistryError>;
}

/// Injectable clock and sleep seam for publish-retry backoff, so retry logic is testable
/// without a real wall-clock wait. The production implementation (`SystemTimeProvider`,
/// `callisto-graph`) wraps `std::time::SystemTime::now()`/`std::thread::sleep`; a test
/// double can record calls and return instantly instead.
pub trait TimeProvider: Send + Sync {
    fn now(&self) -> std::time::SystemTime;
    fn sleep(&self, duration: Duration);
}

/// Redacts every occurrence of any non-empty string in `secrets` from
/// `text`, replacing each with `[REDACTED]`, then strips any URL userinfo
/// component (`REDACTED` -> `scheme://host`) regardless of
/// whether it matched a known secret.
///
/// Callers use this on raw subprocess stderr before it's embedded in a
/// [`RegistryError`] and, downstream, a JSON report or CI log — registry
/// CLIs (`cargo publish`, `npm publish`, `twine upload`) can echo a
/// credential verbatim in their own error diagnostics on auth failure.
///
/// Pure and injectable (`secrets` rather than reading the environment
/// directly) so it stays deterministic and test-friendly; see
/// [`known_credential_env_values`] for the real caller-side source of
/// `secrets`.
pub fn redact_known_secrets(text: &str, secrets: &[String]) -> String {
    let mut redacted = text.to_string();
    for secret in secrets {
        if !secret.is_empty() {
            redacted = redacted.replace(secret.as_str(), "[REDACTED]");
        }
    }
    redact_url_userinfo(&redacted)
}

/// Filters an env-var snapshot down to registry-credential values this
/// codebase's publish flow reads: fixed `NPM_TOKEN`/`TWINE_PASSWORD`/
/// `CARGO_REGISTRY_TOKEN`/`GITHUB_TOKEN`/`GH_TOKEN` names, plus any
/// `CARGO_REGISTRIES_<NAME>_TOKEN` (operator-configured, unbounded name,
/// so matched by pattern). `GITHUB_TOKEN`/`GH_TOKEN` cover GitHub Actions'
/// ambient credential -- `redact_url_userinfo` already catches its most
/// realistic leak shape (an authenticated remote URL) independently, but
/// matching the env var names directly is cheap insurance against other
/// leak shapes.
///
/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
/// rather than reading the environment directly -- same
/// `env: impl Fn(&str) -> Result<String, VarError>` pattern
/// `callisto-cli`'s `check_credentials` uses, for the same reason:
/// deterministic, no process-env mutation in tests.
pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
    vars.filter(|(key, value)| {
        !value.is_empty()
            && (matches!(
                key.as_str(),
                "NPM_TOKEN" | "TWINE_PASSWORD" | "CARGO_REGISTRY_TOKEN" | "GITHUB_TOKEN" | "GH_TOKEN"
            ) || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_TOKEN")))
    })
    .map(|(_, value)| value)
    .collect()
}

/// Strips a URL's userinfo (`user:pass@` between `scheme://` and the
/// host) from every `scheme://...` occurrence in `text`, replacing it
