    /// a `since_ref` that is given but does not resolve is
    /// [`CommitWalkError::RefNotFound`], never a silent unbounded walk.
    fn commits_since(
        &self,
        since_ref: Option<&str>,
        pathspecs: &[PathBuf],
    ) -> Result<Vec<CommitRecord>, CommitWalkError>;
}

